    internal sealed class ExpeditionLedgerRecord
    {
        public int Schema { get; set; }
        public long Sequence { get; set; }
        public string Utc { get; set; }
        public string Event { get; set; }
        public string MissionId { get; set; }
        public string BranchId { get; set; }
        public string StepId { get; set; }
        public string Detail { get; set; }
        public string MissionFingerprint { get; set; }
        public string PrevHash { get; set; }
        public string EntryHash { get; set; }
        public override string ToString() { return Sequence.ToString("000000", CultureInfo.InvariantCulture) + "   ·   " + (Utc ?? "") + "   ·   " + (Event ?? "EVENT") + "   ·   " + (MissionId ?? "") + "   ·   " + ExpeditionKernel.Short(EntryHash); }
    }

    internal sealed class ExpeditionCommandStore
    {
        public int Schema { get; set; }
        public long Revision { get; set; }
        public string UpdatedUtc { get; set; }
        public string ActiveMissionId { get; set; }
        public List<ExpeditionMission> Missions { get; set; }
        public ExpeditionCommandStore() { Schema = 1; Missions = new List<ExpeditionMission>(); }
    }

