        public static void OpenFromWorldNode(Window owner, DeepSystemsContext ctx, WorldIndex index, string nodeId) { if (index == null || String.IsNullOrWhiteSpace(nodeId)) { Open(owner,ctx); return; } WorldNode source; if (!index.Nodes.TryGetValue(nodeId,out source)) { Open(owner,ctx); return; } Project(owner,ctx,"WORLD",source,nodeId,"World object captured as an expedition source snapshot."); }
